CREATE OR REPLACE FUNCTION public.car_update_page(p_car uuid, p_limit integer DEFAULT 50, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, title text, intro text, body jsonb, published_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p.id, p.title, p.intro, p.body, p.published_at
  from public.activity_posts p
  where p.car_id = p_car
    and p.published_at is not null
    and (p_before_at is null or p_before_id is null
         or (p.published_at, p.id) < (p_before_at, p_before_id))
  order by p.published_at desc, p.id desc
  limit least(greatest(coalesce(p_limit, 50), 1), 101);
$function$;

